import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useEffect, useState } from "react";

export default function Profile() {
  const [profile, setProfile] = useState({
    fullName: "",
    email: "",
    phone: "",
    role: "Software engineer", // static
    bio: ""
  });

  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  // Fetch logged-in user data
  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token"); // JWT token
      if (!token) return;

      try {
        const response = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (response.ok) {
          const data = await response.json();
          setProfile({
            fullName: `${data.first_name || ""} ${data.last_name || ""}`,
            email: data.email || "",
            phone: data.profile?.phone || "",
            bio: data.profile?.bio || "",
            role: "Software engineer"
          });
        } else {
          console.error("Failed to fetch profile");
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem("token");
    if (!token) return;

    const [first_name, ...rest] = profile.fullName.split(" ");
    const last_name = rest.join(" ");

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/users/me/`, {
        method: "PUT", // or PATCH if you want partial update
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          first_name,
          last_name,
          email: profile.email,
          profile: {
            phone: profile.phone,
            bio: profile.bio
          }
        })
      });

      if (response.ok) {
        setMessage("Profile updated successfully!");
      } else {
        const data = await response.json();
        console.error("Update error:", data);
        setMessage("Failed to update profile");
      }
    } catch (err) {
      console.error(err);
      setMessage("Network error. Try again later.");
    }
  };

  if (loading) return <p>Loading profile...</p>;

  return (
    <div className="spacebt">
      <div id="profile" className="page active" >
        <div className="page-header" style={{ marginLeft: "16px", marginTop: "19px" }}>
          <h1 className="page-title">My Profile</h1>
          <p className="page-subtitle">Manage your personal information</p>
        </div>

        <div className="profile-form">
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label">Full Name</label>
              <input
                type="text"
                className="form-control"
                name="fullName"
                value={profile.fullName}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">Email Address</label>
              <input
                type="email"
                className="form-control"
                name="email"
                value={profile.email}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">Phone Number</label>
              <input
                type="tel"
                className="form-control"
                name="phone"
                value={profile.phone}
                onChange={handleChange}
              />
            </div>

            <div className="form-group">
              <label className="form-label">Role</label>
              <input
                type="text"
                className="form-control"
                value={profile.role}
                readOnly
              />
            </div>

            <div className="form-group">
              <label className="form-label">Bio</label>
              <textarea
                className="form-control"
                name="bio"
                rows="4"
                value={profile.bio}
                onChange={handleChange}
              ></textarea>
            </div>

           
          </form>
          {message && <p style={{ marginLeft: "18px", marginTop: "10px", color: "green" }}>{message}</p>}
        </div>
      </div>
    </div>
  );
}
